import{_ as a,o as i,c as t,ah as o}from"./chunks/framework.504LQ1l3.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"changelog-2026.4.1.md","filePath":"changelog-2026.4.1.md"}'),r={name:"changelog-2026.4.1.md"};function s(n,e,l,d,c,g){return i(),t("div",null,[...e[0]||(e[0]=[o('<h2 id="_2026-4-1-beta" tabindex="-1">[2026.4.1-beta] <a class="header-anchor" href="#_2026-4-1-beta" aria-label="Permalink to &quot;[2026.4.1-beta]&quot;">​</a></h2><h3 id="sixth-public-beta-release" tabindex="-1">Sixth Public Beta Release <a class="header-anchor" href="#sixth-public-beta-release" aria-label="Permalink to &quot;Sixth Public Beta Release&quot;">​</a></h3><p>The <strong>AI Security Gateway</strong> is a unified security platform providing real-time monitoring, policy enforcement, and threat detection for Large Language Model (LLM) APIs and Model Context Protocol (MCP) servers. This release introduces <strong>Session Quarantine</strong> (kill switch), <strong>Accumulated Session Risk Scoring</strong>, <strong>Scope Change Auto-Pause</strong>, <strong>Cross-Chain Trace Correlation</strong>, <strong>Guardrail Confidence Thresholds</strong>, <strong>Skill Package Registry &amp; Distribution</strong>, and <strong>Skill Version Diff Analysis</strong>, implementing key controls from the AWARE Framework for AI agent governance and expanding the Skill Security Hub into a curated skill distribution platform.</p><hr><h4 id="🔒-session-quarantine-kill-switch" tabindex="-1">🔒 Session Quarantine (Kill Switch) <a class="header-anchor" href="#🔒-session-quarantine-kill-switch" aria-label="Permalink to &quot;🔒 Session Quarantine (Kill Switch)&quot;">​</a></h4><p>A surgical kill switch that blocks individual user sessions without stopping the entire proxy. Administrators can quarantine specific OAuth users, API keys, or IP addresses, and all further requests from that session are immediately rejected with HTTP 403.</p><ul><li><strong>Per-session blocking</strong> across HTTP, WebSocket, and SSE transports for both MCP and LLM proxies</li><li><strong>Active session discovery</strong>: The quarantine modal shows all sessions that made requests in the last 24 hours, with API key name, masked key prefix, request count, and last seen time</li><li><strong>TTL support</strong>: Quarantine entries can auto-expire after a configurable duration, or persist permanently until manually released</li><li><strong>Bulk release</strong>: Release all quarantined sessions for a proxy in one action</li><li><strong>Audit logging</strong>: All quarantine and release actions are logged with full admin attribution</li><li><strong>Alert deduplication</strong>: Blocked request alerts are rate-limited to one per session per minute to prevent alert floods</li></ul><hr><h4 id="📊-accumulated-session-risk-scoring" tabindex="-1">📊 Accumulated Session Risk Scoring <a class="header-anchor" href="#📊-accumulated-session-risk-scoring" aria-label="Permalink to &quot;📊 Accumulated Session Risk Scoring&quot;">​</a></h4><p>Tracks cumulative risk per user session across multiple requests. Each request&#39;s risk score is added to a running total that decays over time, with escalating responses as thresholds are exceeded.</p><ul><li><strong>Time-decaying accumulation</strong>: Risk halves every 30 minutes, preventing normal activity from permanently accumulating</li><li><strong>Four escalation thresholds</strong>: Warn (100), Rate Limit (200), Escalate (300), Block (500)</li><li><strong>Auto-quarantine</strong>: Sessions exceeding the block threshold are automatically quarantined without manual intervention</li><li><strong>Risk visibility</strong>: The quarantine modal shows per-session risk levels with colour-coded badges (green/yellow/orange/red) and a &quot;Reset Risk&quot; action per session</li><li><strong>Severity-based alerts</strong>: Each new escalation generates an alert at the appropriate severity level</li></ul><hr><h4 id="⏸️-scope-change-auto-pause" tabindex="-1">⏸️ Scope Change Auto-Pause <a class="header-anchor" href="#⏸️-scope-change-auto-pause" aria-label="Permalink to &quot;⏸️ Scope Change Auto-Pause&quot;">​</a></h4><p>When rug-pull detection identifies significant tool or agent card changes, the proxy can be automatically paused, requiring administrator re-approval before resuming.</p><ul><li><strong>Severity-based decision logic</strong>: Critical/High severity changes trigger immediate pause; 3+ Medium severity changes trigger pause; Low severity generates alerts only</li><li><strong>Manual pause</strong>: Administrators can manually pause any proxy for security review with a reason</li><li><strong>Review modal</strong>: Shows the pause reason, timestamp, detected changes with severity badges, and an &quot;Approve &amp; Resume&quot; button</li><li><strong>Opt-in per proxy</strong>: Controlled via the <code>scope_change_auto_pause</code> proxy setting (disabled by default)</li></ul><hr><h4 id="🔗-cross-chain-trace-correlation" tabindex="-1">🔗 Cross-Chain Trace Correlation <a class="header-anchor" href="#🔗-cross-chain-trace-correlation" aria-label="Permalink to &quot;🔗 Cross-Chain Trace Correlation&quot;">​</a></h4><p>W3C trace context is now propagated through Agent-to-Agent (A2A) invocations, enabling multi-hop agent workflows to appear as a single distributed trace in Jaeger, Langfuse, or any OTLP-compatible backend.</p><ul><li><strong>Automatic header injection</strong>: Outgoing A2A HTTP requests include <code>traceparent</code> and <code>tracestate</code> headers via OpenTelemetry-instrumented transport</li><li><strong>Audit trail enrichment</strong>: <code>trace_id</code> and <code>span_id</code> are recorded in every agent invocation audit log for cross-reference</li><li><strong>Zero configuration</strong>: Works automatically when tracing is enabled (<code>TRACING_ENABLED=true</code>)</li></ul><hr><h4 id="🎯-guardrail-confidence-thresholds" tabindex="-1">🎯 Guardrail Confidence Thresholds <a class="header-anchor" href="#🎯-guardrail-confidence-thresholds" aria-label="Permalink to &quot;🎯 Guardrail Confidence Thresholds&quot;">​</a></h4><p>Guardrail providers can now be configured with a minimum confidence threshold. Violations reported below the threshold are downgraded from block to monitor, reducing false positives while still logging the finding for review.</p><ul><li><strong>Per-provider threshold</strong>: Set <code>min_confidence_threshold</code> (0.0–1.0) on any guardrail provider configuration</li><li><strong>Backward compatible</strong>: Default threshold of 0 preserves existing behaviour (all violations processed at face value)</li><li><strong>Transparent downgrade logging</strong>: Downgraded violations are logged with provider name, reported confidence, and configured threshold</li></ul><hr><h4 id="📦-skill-package-registry-distribution" tabindex="-1">📦 Skill Package Registry &amp; Distribution <a class="header-anchor" href="#📦-skill-package-registry-distribution" aria-label="Permalink to &quot;📦 Skill Package Registry &amp; Distribution&quot;">​</a></h4><p>The Skill Security Hub now includes a <strong>Package Registry</strong>: admins upload skill packages (ZIP files) that are scanned, stored, and made available for download by AI agents via MCP. This transforms the Hub from analysis-only into a curated skill distribution platform.</p><ul><li><strong>Persistent package storage</strong>: Uploaded ZIP files are stored on disk in a content-hash-based directory structure, configurable via <code>SKILL_PACKAGE_STORAGE_PATH</code> (defaults to <code>./data/skill-packages</code>)</li><li><strong>Automatic package creation</strong>: ZIP uploads via the admin UI now persist the file and create a <code>SkillPackage</code> record linked to the registry entry, no separate upload step needed</li><li><strong>MCP <code>download_skill</code> tool</strong>: AI agents can download approved skill packages directly via MCP. Only skills with status <code>approved</code> and an uploaded package are downloadable. Returns base64-encoded ZIP content with filename, size, and content hash</li><li><strong>MCP <code>search_skills</code> tool</strong>: Rich search across the registry with filters for query text, category, risk level, author, and package availability (<code>has_package</code>). Returns download counts per skill, richer than the existing <code>list_approved_skills</code></li><li><strong>Download audit trail</strong>: Every package download is recorded with agent name, IP address, and timestamp in a dedicated <code>skill_downloads</code> table for compliance tracking</li><li><strong>Packages tab</strong>: New tab in the Skill Security Hub UI showing all uploaded packages with file name, size, download count, skill.json status, uploader, and date. Includes download and delete actions for admins</li><li><strong>skill.json manifest support</strong>: When a ZIP contains a <code>skill.json</code> file, the Gateway stores its contents for future manifest validation and capability declaration</li></ul><hr><h4 id="🔀-skill-version-comparison-diff-analysis" tabindex="-1">🔀 Skill Version Comparison &amp; Diff Analysis <a class="header-anchor" href="#🔀-skill-version-comparison-diff-analysis" aria-label="Permalink to &quot;🔀 Skill Version Comparison &amp; Diff Analysis&quot;">​</a></h4><p>When a skill is re-submitted with changed source code, reviewers can now instantly see what changed, no more reviewing all findings from scratch.</p><ul><li><strong>Finding diff</strong>: Shows new findings (added risks), resolved findings (improvements), and unchanged count between two versions of the same skill</li><li><strong>Risk score delta</strong>: Displays the net risk score change with breakdown, so reviewers see at a glance whether an update improved or worsened security posture</li><li><strong>Automated recommendations</strong>: Generates human-readable review guidance (e.g., &quot;This update resolved 2 High findings and added none. Recommend re-approval.&quot;)</li><li><strong>Compare Versions button</strong>: Appears in the Registry tab for skills with more than one submission. Opens a diff modal with colour-coded findings and the recommendation</li><li><strong>MCP <code>compare_skill_versions</code> tool</strong>: AI agents can programmatically compare two versions of a skill, useful for automated CI/CD pipelines and agent-driven security reviews</li><li><strong>REST endpoint</strong>: <code>GET /api/v1/security/skills/registry/{id}/diff</code> with optional <code>previous_id</code> parameter (auto-detected if omitted)</li></ul>',31)])])}const p=a(r,[["render",s]]);export{h as __pageData,p as default};
